def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = []
    sane_prev_bids = []
    all_prev_bids = []
    urgent_opponents = 0

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)
            if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 2:
                urgent_opponents += 1
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                all_prev_bids.append(bid)
                if bid <= 100:
                    sane_prev_bids.append(bid)

    if not alive_opponents:
        return max(0.0, min(budget, 8.0))

    highest_sane = max(sane_prev_bids) if sane_prev_bids else 0.0
    highest_any = max(all_prev_bids) if all_prev_bids else 0.0

    scarcity = 0
    if supply <= 16:
        scarcity = 3
    elif supply <= 19:
        scarcity = 2
    elif supply <= 22:
        scarcity = 1

    my_urgency = 0
    if hp <= 2 or no_water_days >= 2:
        my_urgency = 3
    elif hp <= 4 or no_water_days >= 1:
        my_urgency = 2
    elif hp <= 6:
        my_urgency = 1

    if my_urgency >= 3:
        target = max(72.0, highest_sane + 6.0)
        if highest_any > 120:
            target = max(target, 88.0)
    elif scarcity >= 3:
        target = max(64.0, highest_sane + 3.0)
    elif scarcity == 2:
        target = max(56.0, highest_sane + 2.0)
    elif scarcity == 1:
        target = max(42.0, highest_sane + 1.0)
    else:
        target = 24.0

    if urgent_opponents >= 2 and scarcity >= 2:
        target += 4.0
    elif urgent_opponents == 0 and hp >= 7 and no_water_days == 0 and supply >= 21:
        target -= 8.0

    if day >= 8 and budget > 200 and my_urgency >= 2:
        target += 5.0

    max_safe = budget
    if hp > 4 and no_water_days == 0:
        max_safe = min(max_safe, DAILY_SALARY * 1.05)
    else:
        max_safe = min(max_safe, DAILY_SALARY * 1.4)

    bid = min(max_safe, target)
    if bid < 0:
        bid = 0.0
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = day_context['day']

    # Identify alive opponents
    alive_ops = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_ops.append((oid, o))

    # If no opponents alive, bid conservatively
    if not alive_ops:
        return float(min(my_status['budget'], DAILY_SALARY * 0.4))

    my_hp = int(my_status['hp'])
    my_budget = float(my_status['budget'])

    # Read yesterday bids from each opponent's previous_trace
    prev_bids = []
    for oid, o in alive_ops:
        prev = o.get('previous_trace', {}) or {}
        bid = prev.get('bid', None)
        if bid is not None:
            try:
                prev_bids.append(float(bid))
            except Exception:
                pass

    # Estimate likely clearing price from yesterday
    if prev_bids:
        sorted_bids = sorted(prev_bids)
        # Top pressure is likely around max; second-highest helps shade
        top = sorted_bids[-1]
        second = sorted_bids[-2] if len(sorted_bids) >= 2 else sorted_bids[-1]

        # If someone was extremely aggressive, shade just below them.
        # Cindy averaged ~138 yesterday; Alex ~105; David low ~50.
        target = second + 0.75
        if top >= DAILY_SALARY * 1.35:
            # Cindy-like pressure; bid near (but under) top
            target = min(top - 2.0, second + 3.0)
        elif top >= DAILY_SALARY * 0.95:
            # Alex-like pressure
            target = min(top - 1.0, second + 2.0)
        else:
            # Low-pressure field
            target = max(DAILY_SALARY * 0.45, second + 1.0)
    else:
        target = DAILY_SALARY * 0.55

    # Adjust for my current hp and budget
    # Healthy (hp high): shade more; low hp: bid harder.
    if my_hp >= 8:
        target *= 0.95
    elif my_hp >= 5:
        target *= 1.00
    elif my_hp >= 3:
        target *= 1.10
    else:
        target *= 1.25

    # Supply-based cap: if supply is low, we should be more competitive.
    # supply range 15-25; higher supply means easier to win.
    if supply <= MIN_SUPPLY + 0.5:
        target *= 1.10
    elif supply >= MAX_SUPPLY - 0.5:
        target *= 0.90

    # Ensure non-negative and within budget
    bid = max(0.0, min(my_budget, float(target)))

    # Avoid bidding too tiny when we likely need water (water requirement 9)
    # Use a floor derived from daily salary to stay competitive.
    min_competitive = DAILY_SALARY * 0.35
    if my_budget >= min_competitive and bid < min_competitive:
        bid = min_competitive

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        return min(my_status['budget'], 20.0)

    yesterday_bids = [o['previous_trace']['bid'] for o in alive_opponents if o.get('previous_trace') and o['previous_trace'].get('bid') is not None]

    avg_bid = sum(yesterday_bids) / len(yesterday_bids) if yesterday_bids else 50.0

    if my_status['hp'] <= 3:
        return min(my_status['budget'], DAILY_SALARY * 1.2)

    bid = min(my_status['budget'], avg_bid * 1.05)
    return max(10.0, bid)
